export const sceneNames={"radio":["Midnight Broadcast","Golden Frequency","Coastal Airwaves","Analog Soul","Arctic Signal","Urban FM","Emerald Lounge","Desert Transmission","Orbital Radio","Afterglow Sessions"],"dj":["Skyline Decks","Warehouse Voltage","Sunset Terrace","Redline Club","Vinyl Atelier","Glacier Stage","Purple Cathedral","Tokyo Basement","Solar Festival","Deep Ocean Club"],"musik":["Arena Lights","Disco Royale","Summer Mainstage","Jazz After Dark","Electric Hall","Neon Roller","Orchestra Noir","Tropical Rhythm","Lunar Sessions","Rose Gold Night"],"gaming":["Cyber Command","Ember Arena","Frost Base","Neon Garage","Jungle Outpost","Orbital Squad","Violet Nexus","Samurai Circuit","Desert Citadel","Retro Arcade"],"shop":["Obsidian Tech","Amber Atelier","Aurelia Beauty","Fashion District","Emerald Home","Solar Sport","Crystal Jewelry","Cafe Collection","Design Objects","Midnight Motors"],"werbung":["Metropolitan Studio","Craft & Copper","Orange Momentum","Fresh Kitchen","Green Horizon","Blue Enterprise","Wellness Sanctuary","Maker Workshop","Property Prestige","Event Vision"]};
const sceneCache=new Map();
export const fixedScenes={'radio-launch-v2':{id:'radio-launch',category:'radio',name:'Broadcast City'},'clan-launch-v2':{id:'clan-launch',category:'gaming',name:'Nexus Citadel'}};
export const isImageScene=s=>s.collection==='premium-v2'||Boolean(fixedScenes[s.collection]);
const cacheKey=s=>s.collection+':'+s.category+':'+s.background;
export function sceneUrl(s,thumb=false){if(fixedScenes[s.collection])return '/demos/'+fixedScenes[s.collection].id+'/fixed-scene'+(thumb?'-thumb':'')+'.jpg';const key=s.category+':'+s.background+(thumb?':thumb':'');if(location.protocol==='file:'&&globalThis.NM_SCENE_DATA?.[key])return globalThis.NM_SCENE_DATA[key];return (location.protocol==='file:'?'./':'/')+'studio-scenes-v2/'+s.category+'/'+String(s.background+1).padStart(2,'0')+(thumb?'-thumb':'')+'.jpg';}
export function getScene(s){return sceneCache.get(cacheKey(s))?.image||null;}
export function loadScene(s){if(!isImageScene(s))return Promise.resolve(null);const key=cacheKey(s);if(sceneCache.has(key))return sceneCache.get(key).promise;const entry={image:null};entry.promise=new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{entry.image=img;resolve(img)};img.onerror=()=>{sceneCache.delete(key);reject(Error('Bildkulisse konnte nicht geladen werden. Bitte erneut auswählen.'))};img.src=sceneUrl(s)});sceneCache.set(key,entry);return entry.promise;}
